        { name: "Gudi Padwa", note: "Marathi new year on the first day of Chaitra, marked by hoisting the gudi, rangoli and festive foods." },
        { name: "Pandharpur Wari / Ashadhi Ekadashi", note: "Roughly 800-year-old, 21-day foot pilgrimage of lakhs of Varkari devotees to Vitthal's temple at Pandharpur, led by the Sant Dnyaneshwar palkhi from Alandi and the Sant Tukaram palkhi from Dehu and culminating on Ashadhi Ekadashi." },
        { name: "Narali Purnima", note: "Koli festival at the end of monsoon when coconuts are offered to the sea before the fishing season resumes." }
