        { name: "Naga tribes", note: "Hill communities (about a quarter of the population) including the Tangkhul, Poumai, Liangmai and others among Manipur's 33 recognized Scheduled Tribes." },
        { name: "Kuki-Chin tribes", note: "Hill communities of the Kuki-Chin group (roughly a sixth of the population), including the Thadou and many kindred tribes." },
        { name: "Meitei Pangal", note: "Manipuri Muslim community of the valley, tracing settlement to soldiers from Sylhet who settled and married locally under King Khagemba in the early 17th century." }
